"""Build a local evidence dossier from retained project artifacts."""
import html,json,re,shutil
from pathlib import Path
import markdown
ROOT=Path(__file__).resolve().parents[1]
DOC=ROOT/"docs"
VENDOR=DOC/"assets/katex"
source=ROOT.parent/"tsimerman_golden_gate/docs/assets/katex"
if not VENDOR.exists():shutil.copytree(source,VENDOR)
def load(path,default=None):
 p=ROOT/path
 return json.loads(p.read_text(encoding="utf-8")) if p.exists() else default
def convert(text):
 text=re.sub(r'(?m)(\|[^\n]*\|)\n\s*\n(?=\|)',r'\1\n',text)
 text=re.sub(r"\\\[(.*?)\\\]",lambda m:'\n<div class="math display" data-tex="'+html.escape(m[1],quote=True)+'"></div>\n',text,flags=re.S)
 text=re.sub(r"\\\((.*?)\\\)",lambda m:'<span class="math" data-tex="'+html.escape(m[1],quote=True)+'"></span>',text,flags=re.S)
 return markdown.markdown(text,extensions=["tables","fenced_code"])
css="""*{box-sizing:border-box}body{overflow-wrap:anywhere;margin:0;background:#0b1018;color:#e5eaf2;font:17px/1.65 system-ui,sans-serif}main{max-width:1160px;margin:auto;padding:36px 24px 80px}h1,h2,h3{line-height:1.2;letter-spacing:-.02em}h1{font-size:clamp(2rem,5vw,3.6rem)}h2{margin-top:2.2em;color:#bde4f0}a{color:#83d5ee}p,li{max-width:95ch}nav{display:flex;flex-wrap:wrap;gap:10px 22px;border-bottom:1px solid #2c394b;padding-bottom:16px}img{width:100%;height:auto;border-radius:8px;background:#101722}figure{margin:28px 0}figcaption{font-size:.9em;color:#afbdce}table{border-collapse:collapse;display:block;overflow:auto;max-width:100%;font-size:.86em}th,td{border:1px solid #304056;padding:10px;vertical-align:top}th{background:#172237}th:nth-child(1),td:nth-child(1){min-width:60px}th:nth-child(2),td:nth-child(2){min-width:125px}th:nth-child(3),td:nth-child(3){min-width:150px}pre{overflow:auto;padding:18px;background:#111d2d}code{overflow-wrap:anywhere}.card{background:#131e2f;border:1px solid #2d4159;padding:20px;border-radius:12px;margin:16px 0}.warning{border-left:4px solid #e3b85b}.math.display{overflow:auto;padding:15px 0}.badge{color:#f6d18a;font-weight:700}small{color:#aabbcc}details{padding:16px;background:#111c2b;margin:10px 0}summary{cursor:pointer}#latex-error{color:#ff9a9a}@media(max-width:600px){main{padding:24px 14px}body{font-size:16px}}"""
def shell(title,content):
 return '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+'</title><link rel="stylesheet" href="assets/katex/katex.min.css"><style>'+css+'</style><body><main><nav><a href="index.html">Evidence dossier</a><a href="SCIENCE.html">Science and proofs</a><a href="ORIGINALITY-AUDIT.html">Originality audit</a><a href="DATA-FEASIBILITY.html">Data inventory</a><a href="BASELINE-REPRODUCTION.html">Baseline</a></nav>'+content+'<p id="latex-error"></p></main><script src="assets/katex/katex.min.js"></script><script>document.querySelectorAll(".math").forEach(e=>{try{katex.render(e.dataset.tex,e,{displayMode:e.classList.contains("display"),throwOnError:true})}catch(x){document.getElementById("latex-error").textContent+=String(x)}});</script></body></html>'
for path in DOC.glob("*.md"):
 (DOC/(path.stem+".html")).write_text(shell(path.stem,convert(path.read_text(encoding="utf-8"))),encoding="utf-8")
steps=load("evidence/steps.json",{"steps":[]})["steps"]
rows=''.join('<tr><td>'+str(s["step"])+'</td><td>'+html.escape(s["verification"])+'</td><td>'+html.escape(s.get("scientific_outcome",""))+'</td><td>'+html.escape(s.get("note",s.get("receipt") or "Pending"))+'</td></tr>' for s in steps)
ref=load("evidence/reference_margin.json",{})
serra=load("evidence/serra_1d_reproduction.json",{})
inventory=load("data/manifest_summary.json",{})
content='<small>PROJECT 4 · EXECUTION EVIDENCE · 18 NOVEMBER 2026</small><h1>From molecular signals<br>to embryonic geometry</h1><div class="card warning"><span class="badge">PROJECT IN PROGRESS — NOT ALL 15 STEPS VERIFIED</span><p>This dossier distinguishes published-model reproduction, mathematical/numerical verification, and biological inference. No new general concept or completed molecular-to-3D-geometry theory has been established.</p></div>'
content+='<h2>What the current evidence supports</h2><p>A reviewed research contract; audited image and cohort data; conditional endpoint prediction on 38 embryos; independently checked mathematics, mechanics and material maps; and a bounded 3D surface audit. The strict baseline reproduction failed. No completed initial-state biological or 3D fold forecast is established. <a href="FINDINGS.html">Read findings, significance and blocked gates</a>.</p>'
content+='<h2>New: an exact-integration certificate transfer fails</h2><p>The controlled-furrowing study now bounds all144 bulk and24 surface contributions at one B-center field. With the old preconditioner, the exact-integral map sends the old center outside its1e-11 cube; its certified displacement exceeds1.6208e-11. This prevents unchanged self-map transfer, while leaving the old finite-quadrature proofs valid and integral-root existence open. <a href="../controlled_furrowing/docs/EXACT-INTEGRATION-BRIDGE.html">Rigorous derivation, figures and receipts</a>. No uniform integral-root, continuum or novel biological claim is made.</p>'
content+='<h2>New: local energy minima for the selected cohort</h2><p>All seventeen selected controlled-furrowing root families now have independently checked positive energy-Hessian certificates throughout their tubes on the same tiny shared parameter cell. The finite-dimensional states are strict local energy minima; common physical histories, continuum stability, biological fit and novelty remain unproved. <a href="../controlled_furrowing/docs/COHORT-ENERGY-STABILITY.html">Proof, figure and retained receipts</a>.</p>'
content+='<h2>Previous checkpoint: a verified common-cell cohort, with scientific limits</h2><p>The controlled-furrowing model now has 17 local stationary-root proofs and 68 uniform static output bounds on one tiny common parameter box. Its maximum residual lies in the safe enclosure [5.18638714, 5.18638737]µm. A single proof-center refinement resolved two numerical cases without changing physics or parameters. Source temporal matching, full material/geometry inference, stable histories, continuum accuracy and novelty remain unresolved. <a href="../controlled_furrowing/docs/SHARED-CELL-COHORT.html">Full theorem, comparison visual and receipts</a>.</p>'
content+='<h2>Earlier finite-model certificates and scientific gaps</h2><p>The controlled-furrowing study now verifies an old weak-load gain family with local energy minima and whole-body geometry, and a distinct actual-M narrow parameter-cell exclusion under a static observer. These are conditional finite-model results. At that earlier checkpoint the all-68 calculation was incomplete; the conditional static result is now linked above. Source-matched temporal calibration, full parameter/geometry inference and continuum prediction remain incomplete. <a href="../controlled_furrowing/docs/PARAMETER-INFERENCE-CHECKPOINT.html">Earlier proof-by-proof checkpoint</a>; <a href="../controlled_furrowing/docs/ACTUAL-M-CELL-EXCLUSION.html">actual-M result and cover visual</a>.</p>'
content+='<h2>Controlled-furrowing five-gate study</h2><p>A separate Drosophila follow-up audits whether small-region calibration can predict larger-region tissue deformation. The scalar reproduction is verified; historical material-column and axis-motion comparisons remain explicit proxies rather than matched biological tests. The 24-by-12 numerical sweep is complete, with substantial spatial sensitivity still unresolved. A source-audited current-radius observer and all-68-entry joint gain calculation are now implemented; all 68 distinct nonlinear candidate targets have completed independent verification, with 5.38–6.25 µm worst-case discrepancies in these fixed material candidates. A subsequent joint material/gain proposal improves the primary fixed-discrete discrepancy to 5.18639 µm while worsening one alternative observation convention; it establishes no material-ratio benefit beyond gain reoptimization. One archived weak-load discrete root now has an independent interval certificate, with continuum accuracy still unresolved. No full physical compatible set, confirmed novel concept, continuum-accuracy certificate or completed biological shape prediction is established. <a href="../controlled_furrowing/docs/index.html">Open the new study, proofs, visuals and receipts</a>; <a href="../controlled_furrowing/docs/JOINT-INFERENCE-PROGRESS.html">read the current joint-inference update</a>.</p>'
content+='<h2>Earlier: planar forecast challenge</h2><p>Initial-only forecasts of extracted image masks were scored 24–84 minutes ahead. The declared affine-versus-persistence criterion fails; all 27 detached-case mask-sensitivity comparisons favor persistence. This is an executed proxy-forecast stress test, not validated biological shape prediction. <a href="PLANAR-FORECAST.html">Read the protocol, sharp conditional bounds, results and limits</a>.</p>'
content+='<h2>Step verification ledger</h2><table><tr><th>Step</th><th>Verification</th><th>Scientific outcome</th><th>Receipt / limit</th></tr>'+rows+'</table>'
content+='<h2>The biological question</h2><p>Do measured molecular and cellular changes determine tissue forces strongly enough to predict motion and shape across interventions? Existing mechanochemical research already supplies much of this bridge. A picture resembling an embryo is insufficient: inputs, constitutive laws, inference uncertainty and out-of-sample consequences must be checked.</p>'
content+='<h2>Data and provenance</h2><p>'+str(inventory.get("file_count","Pending"))+' source TIFFs; '+str(inventory.get("total_source_bytes","Pending"))+' bytes in the indexed image package. Fully downloaded files are distinguished from header-only inspections. Movie/endpoint pairing, channel conflicts, exported-axis ambiguity, source spreadsheets and physical calibration are documented rather than assumed.</p>'
for path,caption in [
 ("assets/planar_forecast_scores.png","Declared initial-only forecasting comparison. Point estimates and sensitivity scenarios do not establish biological uncertainty coverage."),
 ("assets/planar_forecast_overlays.png","Extracted target-mask outlines versus frozen forecasts. The measurement and mechanochemical-transfer limitations remain unpassed."),
 ("assets/margin_reference.png","Published periodic-law structure with explicitly chosen dimensionless parameters. This is a mathematical benchmark, not an embryo fit or nonlinear PDE certificate."),
 ("assets/serra_equilibria.png","Separate Serra2023 published equilibrium/spectrum result reproduced and checked with exact rational exponential brackets. No new mechanism claimed."),
 ("../data/derived/observation_registered_flow_and_strain_dark.png","Image-derived observations; see the pipeline receipt for masks, registration assumptions and biological validation limits."),
 ("assets/endpoint_response.png","Retrospective response prediction from measured endpoint deformation; distinct from a forecast from initial state."),
 ("assets/three_d_public_meshes.png","Public derived cranial surfaces at equal physical scale. Source labels and topology failures remain unresolved; no3Dmechanics validation."),
 ("figures/baseline_intact_default.png","Published-baseline comparison. Agreement and strict failures must be read from the quantitative receipt; visual similarity is not a PASS."),
 ("assets/stokes_benchmark.png","Manufactured unit-square mechanics benchmark; separate from avian biological validation."),
 ("assets/baseline_mesh_conditioning_prefix_timeline.png","Archived-initial-mesh controls: exact serialized agreement through 0.45 hours, then a locked-tolerance counterexample at the first regenerated-mesh solve. This is not a biological refutation.")
]:
 if (DOC/path).exists():content+='<figure><img src="'+path+'" alt="'+html.escape(caption,quote=True)+'"><figcaption>'+caption+'</figcaption></figure>'
content+='<h2>Retained evidence</h2><ul>'
for path in sorted((ROOT/"evidence").glob("*")):
 if path.is_file() and path.suffix in (".json",".md",".log") and path.stat().st_size<300000:
  content+='<li><a href="../evidence/'+path.name+'">'+html.escape(path.name)+'</a></li>'
content+='</ul><h2>Scientific documents</h2><ul>'
for path in sorted(DOC.glob("*.md")):content+='<li><a href="'+path.stem+'.html">'+html.escape(path.stem.replace("-"," "))+'</a></li>'
content+='</ul><h2>Completion boundary</h2><p>A verified negative audit or an identified code defect is a legitimate result, but neither completes the biological prediction and3Dvalidation gates. Missing evidence remains visible. Internal AI review is not external expert review.</p>'
(DOC/"index.html").write_text(shell("Embryo geometry — evidence dossier",content),encoding="utf-8")
(ROOT/"index.html").write_text('<!doctype html><meta charset="utf-8"><meta http-equiv="refresh" content="0;url=docs/index.html"><a href="docs/index.html">Open the embryonic geometry dossier</a>',encoding="utf-8")
print(json.dumps({"html_pages":len(list(DOC.glob("*.html"))),"landing":"docs/index.html"}))

